iss</button><button class="btn btn-primary btn-sm ai-assign" data-id="<?=(int)$r['id']?>">Assign</button><?php elseif(!$is_admin&&in_array($r['status'],['Pending Review','Accepted'],true)&&empty($r['registration_id'])&&$r['training_status']!=='Cancelled'): ?><button class="btn btn-primary btn-sm ai-apply" data-id="<?=(int)$r['training_id']?>">Apply</button><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
