<?php if($is_admin): ?><div class="modal fade" id="analysisModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="analysisForm"><div class="modal-header"><h5 class="modal-title">Run Training Needs Analysis</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><label class="form-label">Analysis Scope</label><select class="form-select" name="employee_id"><option value="">All active and probationary employees</option><?php foreach($employees as $e):if(!in_array($e['status'],['Active','Probationary'],true))continue;?><option value="<?=(int)$e['id']?>"><?=htmlspecialchars($e['employee_code'].' - '.$e['first_name'].' '.$e['last_name'])?></option><?php endforeach;?></select><div class="alert alert-light border mt-3 mb-0 small">The system uses department, position, skill gaps, completion history, and related assessment outcomes. It does not use addresses, contact details, salary, or government identifiers.</div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Run Analysis</button></div></form></div></div></div><?php endif; ?>
<script>$(function(){const csrf=<?=json_encode($csrf)?>,send=(url,data)=>$.post(url,data,null,'json').done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else showErrorDialog(r.message)}).fail(x=>showErrorDialog(x.responseJSON?.message||'Request failed.'));const table=$.fn.DataTable.isDataTable('#aiRecommendationsTable')?$('#aiRecommendationsTable').DataTable():null;$('#aiPriorityFilter').change(function(){if(table)table.search(this.value).draw()});$('#aiDepartmentFilter,#aiPositionFilter').change(function(){if(table)table.search([$('#aiDepartmentFilter').val(),$('#aiPositionFilter').val()].filter(Boolean).join(' ')).draw()});$('.ai-explain').click(function(){let b={};try{b=JSON.parse(this.dataset.breakdown||'{}')}catch(e){};const rows=Object.entries(b).map(([k,v])=>`<div class="d-flex justify-content-between border-bottom py-2"><span>${k.replaceAll('_',' ')}</span><strong>${Number(v).toFixed(1)} pts</strong></div>`).join('');Swal.fire({icon:'info',iconHtml:'<i class="fa-solid fa-wand-magic-sparkles" aria-hidden="true"></i>',title:this.dataset.title,html:`<p class="core3-detail-reason">${$('<div>').text(this.dataset.reason).html()}</p><div class="core3-detail-breakdown">${rows}</div>`,showCloseButton:true,buttonsStyling:false,confirmButtonText:'Close',customClass:{popup:'core3-detail-dialog',icon:'core3-detail-icon',title:'core3-detail-title',htmlContainer:'core3-detail-copy',actions:'core3-detail-actions',confirmButton:'core3-detail-confirm',closeButton:'core3-detail-close'}})});<?php if($is_admin): ?>$('#analysisForm').submit(function(e){e.preventDefault();send('index.php?page=training_recommendations_analyze',$(this).serialize())});$('#historicalForm').submit(function(e){e.preventDefault();send('index.php?page=training_history_store',$(this).serialize())});$('.ai-review').click(function(){send('index.php?page=training_recommendations_review',{id:this.dataset.id,decision:this.dataset.decision,csrf_token:csrf})});$('.ai-dismiss').click(function(){const id=this.dataset.id;Swal.fire({title:'Dismiss Recommendation',input:'textarea',inputLabel:'Optional HR reason',showCancelButton:true,confirmButtonText:'Dismiss'}).then(x=>{if(x.isConfirmed)send('index.php?page=training_recommendations_review',{id,decision:'Dismissed',dismissed_reason:x.value||'',csrf_token:csrf})})});$('.ai-assign').click(function(){const id=this.dataset.id;confirmAction('Assign Recommended Training','This uses the existing training assignment workflow and still requires employee participation.','Assign Training',()=>send('index.php?page=training_recommendations_assign',{id,csrf_token:csrf}))});<?php else: ?>$('.ai-apply').click(function(){const course_id=this.dataset.id;confirmAction('Apply for Recommended Training','Submit this recommendation through the existing enrollment workflow?','Apply',()=>send('index.php?page=training_register',{course_id,csrf_token:csrf}))});<?php endif; ?>});</script>
